def down2(img):
    h, w = len(img), len(img[0])
    return [[(img[2*i][2*j] + img[2*i+1][2*j] + img[2*i][2*j+1] + img[2*i+1][2*j+1]) // 4
             for j in range(w//2)] for i in range(h//2)]

def corr_at(img, T, i, j):
    return sum(img[i+a][j+b]*T[a][b] for a in range(len(T)) for b in range(len(T[0])))

T = [[200,200, 10, 10],
     [200,200, 10, 10],
     [ 10, 10, 10, 10],
     [ 10, 10, 10, 10]]
img = [[10]*16 for _ in range(16)]
for r in range(4):
    for c in range(4):
        img[8+r][6+c] = T[r][c]
brute = (16-4+1) ** 2
ci, cT = down2(img), down2(T)
coarse_scores = [[corr_at(ci, cT, i, j) for j in range(7)] for i in range(7)]
