refined = set()
for i, j in hits:
    for x in (2*i-1, 2*i, 2*i+1):
        for y in (2*j-1, 2*j, 2*j+1):
            if 0 <= x <= 12 and 0 <= y <= 12:
                refined.add((x, y))
best = max((corr_at(img, T, x, y), x, y) for x, y in refined)
print("Brute force: %d full-cost window evaluations." % brute)
print("Pyramid: %d coarse evaluations -> %d candidate(s) %s" % (49, len(hits), hits))
print("         -> %d full-res verifications in the 3x3 neighborhoods." % len(refined))
print("Verified peak %d at (%d,%d). Same answer, ~1/3 the arithmetic." % best)
